const clean=s=>String(s??'').trim();
const num=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d;
const nil=v=>clean(v)||null;
const idempotencyKey=req=>{const value=clean(req.get('x-idempotency-key'));return /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)?value:null};
const emailOk=s=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
