const roleLabel={owner:'Firma Sahibi',manager:'Yönetici',technician:'Teknisyen',operator:'Operatör',viewer:'Görüntüleyici'};
async function q(text,params=[]){return pool.query(text,params)}
const cookieOptions=()=>({httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax',path:'/'});
function setCookie(res,token){res.cookie('dm_token',token,{...cookieOptions(),maxAge:SESSION_DAYS*24*60*60*1000})}
function clearCookie(res){res.clearCookie('dm_token',cookieOptions())}
function requestIp(req){return String(req.ip||req.socket?.remoteAddress||'').slice(0,80)}
function deviceName(req){const ua=String(req.get?.('user-agent')||'').slice(0,500);let browser=/Edg\//.test(ua)?'Edge':/Chrome\//.test(ua)?'Chrome':/Firefox\//.test(ua)?'Firefox':/Safari\//.test(ua)?'Safari':'Tarayıcı';let os=/Android/.test(ua)?'Android':/iPhone|iPad/.test(ua)?'iOS':/Windows/.test(ua)?'Windows':/Mac OS/.test(ua)?'macOS':/Linux/.test(ua)?'Linux':'Cihaz';return `${browser} • ${os}`}
function signSession(user,sessionId,mfaVerified){return jwt.sign({id:user.id,sid:sessionId,sv:Number(user.session_version||0),mfa:!!mfaVerified},JWT_SECRET,{expiresIn:`${SESSION_DAYS}d`})}
async function issueSession(user,req,res,mfaVerified=false){const id=crypto.randomUUID(),expires=new Date(Date.now()+SESSION_DAYS*86400000);await q('INSERT INTO auth_sessions(id,user_id,user_agent,ip,device_name,mfa_verified,expires_at) VALUES($1,$2,$3,$4,$5,$6,$7)',[id,user.id,String(req.get('user-agent')||'').slice(0,500),requestIp(req),deviceName(req),!!mfaVerified,expires]);setCookie(res,signSession(user,id,mfaVerified));return id}
async function auth(req,res,next){const raw=req.cookies.dm_token;if(!raw)return res.status(401).json({error:'Giriş gerekli'});try{const token=jwt.verify(raw,JWT_SECRET);if(!token.sid)return clearCookie(res),res.status(401).json({error:'Güvenlik güncellemesi nedeniyle yeniden giriş yapın'});const u=(await q('SELECT id,name,email,role,is_active,platform_admin,email_verified_at,session_version,mfa_enabled FROM users WHERE id=$1',[token.id])).rows[0];if(!u?.is_active){clearCookie(res);return res.status(403).json({error:'Hesabınız devre dışı'})}if(EMAIL_VERIFICATION_REQUIRED&&!u.email_verified_at){clearCookie(res);return res.status(403).json({error:'E-posta adresinizi doğrulamanız gerekli',code:'EMAIL_VERIFICATION_REQUIRED'})}const session=(await q('SELECT id,mfa_verified,expires_at,revoked_at FROM auth_sessions WHERE id=$1 AND user_id=$2',[token.sid,u.id])).rows[0];if(!session||!sessionStateValid({tokenVersion:token.sv,userVersion:u.session_version||0,revokedAt:session.revoked_at,expiresAt:session.expires_at})){clearCookie(res);return res.status(401).json({error:'Oturum geçersiz veya güvenlik nedeniyle sonlandırıldı'})}await q('UPDATE auth_sessions SET last_seen_at=NOW() WHERE id=$1',[session.id]);const st=await getSystemSettings();if(st.maintenance_mode===true&&!u.platform_admin)return res.status(503).json({error:'Sistem bakım modunda. Lütfen daha sonra tekrar deneyin.'});req.user=u;req.authSession={...session,id:token.sid,mfa_verified:!!session.mfa_verified};next()}catch(e){if(e?.name==='JsonWebTokenError'||e?.name==='TokenExpiredError'){clearCookie(res);return res.status(401).json({error:'Oturum geçersiz'})}next(e)}}
async function siteAdmin(req,res,next){try{if(!req.user?.platform_admin)return res.status(403).json({error:'Platform yöneticisi yetkisi gerekli'});if(ADMIN_MFA_REQUIRED&&(!req.user.mfa_enabled||!req.authSession?.mfa_verified))return res.status(403).json({error:'Yönetici işlemleri için MFA kurulumu ve doğrulaması gerekli',code:'ADMIN_MFA_REQUIRED'});next()}catch(e){next(e)}}
function permit(...roles){return(req,res,next)=>{if(req.user?.platform_admin||roles.includes(req.company?.role))return next();return res.status(403).json({error:`Bu işlem için yetkiniz yok (${roleLabel[req.company?.role]||'rol'})`})}}
function healthScore(m){let s=100;if(m.status==='Arızalı')s-=35;else if(m.status==='Bakımda')s-=15;else if(m.status==='Devre dışı')s-=25;if(m.criticality==='Kritik')s-=5;s-=Math.min(24,num(m.open_faults)*6);s-=Math.min(16,num(m.critical_faults)*8);s-=Math.min(21,num(m.overdue_maintenance)*7);s-=Math.min(9,num(m.due30)*3);if(num(m.faults90)>=3)s-=8;if(m.last_maintenance_date){const days=(Date.now()-new Date(m.last_maintenance_date).getTime())/86400000;if(days>180)s-=10}else if(num(m.hours)>250)s-=8;return Math.max(5,Math.min(100,Math.round(s)))}
function slug(s){return clean(s).toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ş/g,'s').replace(/ç/g,'c').replace(/ö/g,'o').replace(/ü/g,'u').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'firma'}
async function addCols(table,cols){for(const c of cols)await q(`ALTER TABLE ${table} ADD COLUMN IF NOT EXISTS ${c}`)}
async function uniqueCompanyCode(name){const base=slug(name);for(let i=0;i<20;i++){const code=(base+'-'+Math.random().toString(36).slice(2,7)).slice(0,60);if(!(await q('SELECT 1 FROM companies WHERE code=$1',[code])).rows.length)return code}return base+'-'+Date.now()}
async function createPersonalCompany(user){const name=`${user.name} Atölyesi`,code=await uniqueCompanyCode(name);const c=(await q('INSERT INTO companies(name,code,owner_user_id) VALUES($1,$2,$3) RETURNING *',[name,code,user.id])).rows[0];await q("INSERT INTO company_members(company_id,user_id,role) VALUES($1,$2,'owner') ON CONFLICT(company_id,user_id) DO UPDATE SET role='owner',is_active=true",[c.id,user.id]);await q('UPDATE users SET active_company_id=$1 WHERE id=$2',[c.id,user.id]);return c}
async function ensureCompanyForUser(userId){let u=(await q('SELECT id,name,active_company_id FROM users WHERE id=$1',[userId])).rows[0];if(!u)return null;let m=(await q(`SELECT c.id,c.name,c.code,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active=true AND c.id=$2`,[userId,u.active_company_id||0])).rows[0];if(!m)m=(await q(`SELECT c.id,c.name,c.code,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active=true ORDER BY cm.id LIMIT 1`,[userId])).rows[0];if(!m){const c=await createPersonalCompany(u);m={...c,role:'owner'}}if(Number(u.active_company_id)!==Number(m.id))await q('UPDATE users SET active_company_id=$1 WHERE id=$2',[m.id,userId]);return m}
async function companyCtx(req,res,next){try{const c=await ensureCompanyForUser(req.user.id);if(!c)return res.status(403).json({error:'Aktif firma bulunamadı'});req.company=c;next()}catch(e){next(e)}}
async function ownMachine(id,companyId){return (await q('SELECT id FROM machines WHERE id=$1 AND company_id=$2 AND archived_at IS NULL',[id,companyId])).rows[0]}
async function ownCompanyMember(id,companyId){if(!id)return true;return (await q('SELECT 1 FROM company_members WHERE user_id=$1 AND company_id=$2 AND is_active=true',[id,companyId])).rows[0]}
const parentTables={maintenance:'maintenance',work_order:'work_orders'};
async function ownOperationalParent(type,id,companyId,db=pool){const table=parentTables[type];if(!table)return null;return (await db.query(`SELECT * FROM ${table} WHERE id=$1 AND company_id=$2`,[id,companyId])).rows[0]}
async function insertChecklistItems(db,companyId,parentType,parentId,items=[]){let position=0;for(const value of Array.isArray(items)?items.slice(0,100):[]){const label=clean(typeof value==='string'?value:value?.label).slice(0,240);if(!label)continue;await db.query(`INSERT INTO checklist_items(company_id,parent_type,parent_id,label,position) VALUES($1,$2,$3,$4,$5)`,[companyId,parentType,parentId,label,position++])}}
async function createNextMaintenance(completed,db){if(completed.recurrence_type==='calendar'&&Number(completed.interval_months)>0){const exists=(await db.query(`SELECT 1 FROM maintenance WHERE company_id=$1 AND template_id=$2 AND status='open' AND archived_at IS NULL`,[completed.company_id,completed.template_id])).rows[0];if(!exists){const next=(await db.query(`INSERT INTO maintenance(user_id,company_id,machine_id,task,due_date,priority,status,note,maintenance_type,frequency,technician_user_id,cost,duration_min,meter_hours,recurrence_type,interval_months,template_id,recurrence_source_id,auto_generated) VALUES($1,$2,$3,$4,($5::date+($6::text||' months')::interval)::date,$7,'open',$8,$9,$10,$11,0,0,0,'calendar',$6,$12,$13,true) RETURNING *`,[completed.user_id,completed.company_id,completed.machine_id,completed.task,completed.due_date,completed.interval_months,completed.priority,completed.note,completed.maintenance_type,completed.frequency,completed.technician_user_id,completed.template_id,completed.id])).rows[0];await db.query(`UPDATE maintenance_templates SET next_due_date=$1,last_generated_at=NOW(),updated_at=NOW() WHERE id=$2`,[next.due_date,completed.template_id]);const template=(await db.query('SELECT checklist_template FROM maintenance_templates WHERE id=$1',[completed.template_id])).rows[0];await insertChecklistItems(db,completed.company_id,'maintenance',next.id,template?.checklist_template||[]);return next}}if(completed.recurrence_type==='hours'&&Number(completed.interval_hours)>0&&completed.template_id){const machine=(await db.query('SELECT hours FROM machines WHERE id=$1 AND company_id=$2',[completed.machine_id,completed.company_id])).rows[0],nextHours=num(machine?.hours)+num(completed.interval_hours);await db.query(`UPDATE maintenance_templates SET next_due_hours=$1,last_generated_at=NOW(),updated_at=NOW() WHERE id=$2`,[nextHours,completed.template_id])}return null}
async function materializeHourMaintenance(companyId,machineId,hours,userId){const templates=(await q(`SELECT t.* FROM maintenance_templates t WHERE t.company_id=$1 AND t.machine_id=$2 AND t.is_active=true AND t.recurrence_type='hours' AND t.next_due_hours IS NOT NULL AND t.next_due_hours<=$3 AND NOT EXISTS(SELECT 1 FROM maintenance m WHERE m.template_id=t.id AND m.status='open' AND m.archived_at IS NULL)`,[companyId,machineId,hours])).rows;let created=0;for(const t of templates){const client=await pool.connect();try{await client.query('BEGIN');const row=(await client.query(`INSERT INTO maintenance(user_id,company_id,machine_id,task,due_date,priority,status,note,maintenance_type,technician_user_id,meter_hours,recurrence_type,interval_hours,next_due_hours,template_id,auto_generated) VALUES($1,$2,$3,$4,CURRENT_DATE,$5,'open',$6,$7,$8,$9,'hours',$10,$9,$11,true) ON CONFLICT (template_id) WHERE template_id IS NOT NULL AND status='open' AND archived_at IS NULL DO NOTHING RETURNING id`,[userId,companyId,machineId,t.title,t.priority,t.note,t.maintenance_type,t.assigned_user_id,t.next_due_hours,t.interval_hours,t.id])).rows[0];if(row){await insertChecklistItems(client,companyId,'maintenance',row.id,t.checklist_template||[]);await client.query('UPDATE maintenance_templates SET last_generated_at=NOW(),updated_at=NOW() WHERE id=$1',[t.id]);created++}await client.query('COMMIT')}catch(error){await client.query('ROLLBACK').catch(()=>{});throw error}finally{client.release()}}return created}
async function audit(req,action,entityType,entityId,details={}){try{await q('INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5,$6::jsonb)',[req.company?.id||null,req.user?.id||null,action,entityType,entityId||null,JSON.stringify(details||{})])}catch(e){console.warn('audit:',e.message)}}
function validDateMonth(v){return /^\d{4}-\d{2}$/.test(String(v||''))?String(v):new Date().toISOString().slice(0,7)}
let settingsCache={at:0,data:{}};
async function getSystemSettings(force=false){if(!force&&Date.now()-settingsCache.at<10000)return settingsCache.data;const rows=(await q('SELECT key,value FROM system_settings')).rows;const data={};for(const r of rows)data[r.key]=r.value;settingsCache={at:Date.now(),data};return data}
async function adminAudit(req,action,targetType,targetId=null,details={}){try{await q('INSERT INTO admin_action_log(admin_user_id,action,target_type,target_id,details,ip,user_agent) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7)',[req.user?.id||null,action,targetType,targetId||null,JSON.stringify(details||{}),String(req.ip||'').slice(0,80),String(req.get?.('user-agent')||'').slice(0,500)])}catch(e){console.warn('admin audit:',e.message)}}
async function loginEvent(req,email,success,userId=null,reason=''){try{await q('INSERT INTO login_events(user_id,email,success,reason,ip,user_agent) VALUES($1,$2,$3,$4,$5,$6)',[userId||null,clean(email).toLowerCase(),!!success,clean(reason).slice(0,160),String(req.ip||'').slice(0,80),String(req.get('user-agent')||'').slice(0,500)])}catch(e){console.warn('login event:',e.message)}}

function resetTokenHash(token){return crypto.createHash('sha256').update(String(token||'')).digest('hex')}
const dummyHashPromise=bcrypt.hash('DijitalMakinaci-Dummy-2026!',12);
async function checkLoginGuard(req,email){const row=(await q(`SELECT COUNT(*) FILTER(WHERE email=$1)::int email_failures,COUNT(*) FILTER(WHERE ip=$2)::int ip_failures FROM login_events WHERE success=false AND created_at>NOW()-INTERVAL '15 minutes'`,[email,requestIp(req)])).rows[0];return Number(row.email_failures)>=5||Number(row.ip_failures)>=20}
function htmlEscape(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function mailConfigured(){return !!(clean(process.env.RESEND_API_KEY)&&clean(process.env.MAIL_FROM||process.env.PASSWORD_RESET_FROM))}
async function sendTransactionalMail(to,subject,html){
 const key=clean(process.env.RESEND_API_KEY),from=clean(process.env.MAIL_FROM||process.env.PASSWORD_RESET_FROM);
 if(!key||!from)return false;
 const body={from,to:[to],subject,html};
 const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${key}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
 if(!r.ok){const t=await r.text().catch(()=>'');throw Error(`E-posta servisi ${r.status}: ${t.slice(0,180)}`)}
 return true;
}
async function sendPasswordResetMail(to,name,resetUrl){return sendTransactionalMail(to,'Dijital Makinacı • Şifre yenileme',`<div style="font-family:Arial,sans-serif;background:#071015;color:#eef5f3;padding:28px"><div style="max-width:560px;margin:auto;background:#0b171d;border:1px solid #20343d;border-radius:16px;padding:28px"><h2 style="margin:0 0 14px;color:#65ef9b">Şifreni yenile</h2><p>Merhaba ${htmlEscape(clean(name)||'kullanıcı')}, Dijital Makinacı hesabın için şifre yenileme isteği aldık.</p><p><a href="${htmlEscape(resetUrl)}" style="display:inline-block;background:#65ef9b;color:#06110a;text-decoration:none;font-weight:700;padding:12px 18px;border-radius:9px">Yeni şifre oluştur</a></p><p style="color:#91a4ab;font-size:13px">Bu bağlantı 30 dakika geçerlidir ve yalnızca bir kez kullanılabilir.</p></div></div>`)}
