async function issueEmailVerification(user,req){if(!mailConfigured())return false;const raw=crypto.randomBytes(32).toString('hex'),hash=resetTokenHash(raw);await q('UPDATE email_verification_tokens SET used_at=NOW() WHERE user_id=$1 AND used_at IS NULL',[user.id]);await q("INSERT INTO email_verification_tokens(user_id,token_hash,expires_at) VALUES($1,$2,NOW()+INTERVAL '24 hours')",[user.id,hash]);const base=(clean(process.env.PUBLIC_BASE_URL)||`${req.protocol}://${req.get('host')}`).replace(/\/$/,'');await sendVerificationMail(user.email,user.name,`${base}/verify-email.html?token=${encodeURIComponent(raw)}`);return true}

const MFA_KEY=crypto.createHash('sha256').update(`${JWT_SECRET}:mfa:v1`).digest();
const BASE32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function base32Encode(buffer){let bits='',out='';for(const byte of buffer)bits+=byte.toString(2).padStart(8,'0');for(let i=0;i<bits.length;i+=5)out+=BASE32[parseInt(bits.slice(i,i+5).padEnd(5,'0'),2)];return out}
function base32Decode(value){let bits='';for(const ch of String(value||'').replace(/=+$/,'').toUpperCase()){const index=BASE32.indexOf(ch);if(index<0)continue;bits+=index.toString(2).padStart(5,'0')}const bytes=[];for(let i=0;i+8<=bits.length;i+=8)bytes.push(parseInt(bits.slice(i,i+8),2));return Buffer.from(bytes)}
function encryptMfaSecret(secret){const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',MFA_KEY,iv),encrypted=Buffer.concat([cipher.update(secret,'utf8'),cipher.final()]);return [iv,cipher.getAuthTag(),encrypted].map(x=>x.toString('base64url')).join('.')}
function decryptMfaSecret(value){const [iv,tag,data]=String(value||'').split('.').map(x=>Buffer.from(x,'base64url'));const decipher=crypto.createDecipheriv('aes-256-gcm',MFA_KEY,iv);decipher.setAuthTag(tag);return Buffer.concat([decipher.update(data),decipher.final()]).toString('utf8')}
function totpCode(secret,time=Date.now()){const counter=Buffer.alloc(8);counter.writeBigUInt64BE(BigInt(Math.floor(time/30000)));const hash=crypto.createHmac('sha1',base32Decode(secret)).update(counter).digest(),offset=hash[hash.length-1]&15;return String((hash.readUInt32BE(offset)&0x7fffffff)%1000000).padStart(6,'0')}
function verifyTotp(secret,code){const normalized=clean(code).replace(/\s/g,'');return /^\d{6}$/.test(normalized)&&[-1,0,1].some(step=>{const expected=totpCode(secret,Date.now()+step*30000);return crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(normalized))})}
function makeRecoveryCodes(){return Array.from({length:8},()=>`${crypto.randomBytes(3).toString('hex').toUpperCase()}-${crypto.randomBytes(3).toString('hex').toUpperCase()}`)}
function recoveryHash(code){return resetTokenHash(clean(code).toUpperCase())}
function passwordProblem(password){if(password.length<10||password.length>128)return 'Şifre 10–128 karakter olmalı';if(!/[a-zçğıöşü]/.test(password)||!/[A-ZÇĞİÖŞÜ]/.test(password)||!/[0-9]/.test(password))return 'Şifre büyük harf, küçük harf ve rakam içermeli';return ''}
async function sendPushToUser(userId,payload){if(!VAPID_PUBLIC_KEY||!VAPID_PRIVATE_KEY)return false;const subscriptions=(await q('SELECT id,endpoint,p256dh,auth FROM push_subscriptions WHERE user_id=$1',[userId])).rows;let sent=false;for(const sub of subscriptions){try{await webpush.sendNotification({endpoint:sub.endpoint,keys:{p256dh:sub.p256dh,auth:sub.auth}},JSON.stringify(payload),{TTL:3600,urgency:payload.level==='critical'?'high':'normal'});await q('UPDATE push_subscriptions SET last_success_at=NOW(),failed_at=NULL WHERE id=$1',[sub.id]);sent=true}catch(error){if([404,410].includes(error.statusCode))await q('DELETE FROM push_subscriptions WHERE id=$1',[sub.id]);else await q('UPDATE push_subscriptions SET failed_at=NOW() WHERE id=$1',[sub.id])}}return sent}
async function notifyUser({userId,companyId,type,level='info',title,body,target='dashboard',dedupeKey,email=false}){const row=(await q(`INSERT INTO user_notifications(user_id,company_id,type,level,title,body,target_url,dedupe_key) VALUES($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT(user_id,dedupe_key) DO UPDATE SET title=EXCLUDED.title,body=EXCLUDED.body,level=EXCLUDED.level,target_url=EXCLUDED.target_url RETURNING *,(xmax=0) inserted`,[userId,companyId,type,level,clean(title).slice(0,220),clean(body).slice(0,2000),`/app?section=${encodeURIComponent(target)}`,dedupeKey])).rows[0];if(row.inserted){const pushed=await sendPushToUser(userId,{title:row.title,body:row.body,url:row.target_url,level});if(pushed)await q('UPDATE user_notifications SET push_sent_at=NOW() WHERE id=$1',[row.id]);if(email&&mailConfigured()){const user=(await q('SELECT email,name FROM users WHERE id=$1',[userId])).rows[0];if(user)try{await sendTransactionalMail(user.email,`Dijital Makinacı • ${row.title}`,`<div style="font-family:Arial,sans-serif;padding:24px"><h2>${htmlEscape(row.title)}</h2><p>Merhaba ${htmlEscape(user.name)},</p><p>${htmlEscape(row.body)}</p><p><a href="${htmlEscape((clean(process.env.PUBLIC_BASE_URL)||'https://dijitalmakinaci.pro')+row.target_url)}">Uygulamada aç</a></p></div>`);await q('UPDATE user_notifications SET email_sent_at=NOW() WHERE id=$1',[row.id])}catch(error){console.error('Bildirim e-postası:',error.message)}}}return row}
async function refreshUserNotifications(user,company){const [maintenanceRows,workRows,faultRows,stockRows]=await Promise.all([q(`SELECT ma.id,ma.task,ma.due_date,m.name machine_name FROM maintenance ma LEFT JOIN machines m ON m.id=ma.machine_id WHERE ma.company_id=$1 AND ma.technician_user_id=$2 AND ma.status='open' AND ma.archived_at IS NULL AND ma.due_date<=CURRENT_DATE+7 LIMIT 40`,[company.id,user.id]),q(`SELECT w.id,w.title,w.due_date,m.name machine_name FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id WHERE w.company_id=$1 AND w.assigned_user_id=$2 AND w.status<>'done' AND w.archived_at IS NULL AND (w.due_date IS NULL OR w.due_date<=CURRENT_DATE+7) LIMIT 40`,[company.id,user.id]),q(`SELECT f.id,f.symptom,f.severity,m.name machine_name FROM faults f LEFT JOIN machines m ON m.id=f.machine_id WHERE f.company_id=$1 AND f.status='open' AND f.severity IN ('Yüksek','Kritik') LIMIT 30`,[company.id]),['owner','manager'].includes(company.role)||user.platform_admin?q(`SELECT id,name,quantity,min_quantity,unit FROM parts WHERE company_id=$1 AND quantity<=min_quantity LIMIT 30`,[company.id]):Promise.resolve({rows:[]})]);for(const row of maintenanceRows.rows)await notifyUser({userId:user.id,companyId:company.id,type:'maintenance',level:new Date(row.due_date)<new Date(new Date().toDateString())?'critical':'warning',title:row.task,body:`${row.machine_name||'Makine'} • ${row.due_date}`,target:'maintenance',dedupeKey:`maintenance:${row.id}:${row.due_date}`,email:true});for(const row of workRows.rows)await notifyUser({userId:user.id,companyId:company.id,type:'work',level:'info',title:row.title,body:`${row.machine_name||'Makine'}${row.due_date?' • '+row.due_date:''}`,target:'workorders',dedupeKey:`work:${row.id}:${row.due_date||'none'}`});if(['owner','manager','technician'].includes(company.role)||user.platform_admin)for(const row of faultRows.rows)await notifyUser({userId:user.id,companyId:company.id,type:'fault',level:row.severity==='Kritik'?'critical':'warning',title:row.symptom,body:`${row.machine_name||'Makine'} • ${row.severity}`,target:'diagnosis',dedupeKey:`fault:${row.id}`,email:row.severity==='Kritik'});for(const row of stockRows.rows)await notifyUser({userId:user.id,companyId:company.id,type:'stock',level:'warning',title:`Düşük stok: ${row.name}`,body:`${row.quantity} ${row.unit} / min ${row.min_quantity}`,target:'parts',dedupeKey:`stock:${row.id}:${row.quantity}`})}
let operationalJobRunning=false;
async function runOperationalJobs(){if(operationalJobRunning)return;operationalJobRunning=true;try{const due=(await q(`SELECT DISTINCT t.company_id,t.machine_id,m.hours,t.created_by FROM maintenance_templates t JOIN machines m ON m.id=t.machine_id AND m.company_id=t.company_id WHERE t.is_active=true AND t.recurrence_type='hours' AND t.next_due_hours IS NOT NULL AND t.next_due_hours<=m.hours AND m.archived_at IS NULL LIMIT 500`)).rows;for(const row of due)await materializeHourMaintenance(row.company_id,row.machine_id,row.hours,row.created_by).catch(error=>console.error('Saat bazlı bakım:',error.message));const members=(await q(`SELECT u.id,u.name,u.email,u.platform_admin,c.id company_id,c.name company_name,c.code company_code,cm.role FROM company_members cm JOIN users u ON u.id=cm.user_id AND u.is_active JOIN companies c ON c.id=cm.company_id WHERE cm.is_active=true ORDER BY cm.id LIMIT 2000`)).rows;for(const row of members)await refreshUserNotifications(row,{id:row.company_id,name:row.company_name,code:row.company_code,role:row.role}).catch(error=>console.error('Bildirim taraması:',error.message))}catch(error){console.error('Operasyon zamanlayıcısı:',error.message)}finally{operationalJobRunning=false}}

