 await addCols('parts',['company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS favorites(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,article_key VARCHAR(180) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,article_key))`);
 await q(`CREATE TABLE IF NOT EXISTS calc_history(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,tool VARCHAR(120) NOT NULL,input_data JSONB DEFAULT '{}'::jsonb,result TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS work_orders(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT REFERENCES machines(id) ON DELETE SET NULL,title VARCHAR(220) NOT NULL,description TEXT DEFAULT '',priority VARCHAR(30) DEFAULT 'Normal',status VARCHAR(30) DEFAULT 'open',assigned_to VARCHAR(160) DEFAULT '',due_date DATE,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,parts_used TEXT DEFAULT '',cost NUMERIC(12,2) DEFAULT 0,downtime_min INTEGER DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('work_orders',['company_id BIGINT','assigned_user_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS machine_measurements(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT NOT NULL REFERENCES machines(id) ON DELETE CASCADE,temperature NUMERIC(10,2),pressure NUMERIC(10,2),current_amp NUMERIC(10,2),voltage NUMERIC(10,2),vibration NUMERIC(10,3),rpm NUMERIC(12,1),note TEXT DEFAULT '',measured_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
