// AUTH
function publicUser(user,extra={}){return {id:user.id,name:user.name,email:user.email,role:user.role,is_active:user.is_active,platform_admin:!!user.platform_admin,email_verified:!!user.email_verified_at,mfa_enabled:!!user.mfa_enabled,...extra}}
async function finishLogin(user,req,res,mfaVerified=false){await ensureCompanyForUser(user.id);await q('UPDATE users SET last_login_at=NOW() WHERE id=$1',[user.id]);await issueSession(user,req,res,mfaVerified);await loginEvent(req,user.email,true,user.id,mfaVerified?'mfa_login':'login');return publicUser(user,{mfa_setup_required:!!(user.platform_admin&&ADMIN_MFA_REQUIRED&&!user.mfa_enabled)})}
app.post('/api/auth/register',async(req,res,next)=>{try{const st=await getSystemSettings();if(st.registrations_enabled===false)return res.status(403).json({error:'Yeni kullanıcı kaydı geçici olarak kapalı'});if(st.maintenance_mode===true)return res.status(503).json({error:'Sistem bakım modunda'});const name=clean(req.body.name),email=clean(req.body.email).toLowerCase(),password=String(req.body.password||''),problem=passwordProblem(password);if(name.length<2)return res.status(400).json({error:'Ad soyad gerekli'});if(!emailOk(email))return res.status(400).json({error:'Geçerli e-posta gir'});if(problem)return res.status(400).json({error:problem});if(EMAIL_VERIFICATION_REQUIRED&&!mailConfigured())return res.status(503).json({error:'E-posta doğrulama servisi yapılandırılmadan yeni kayıt açılamaz'});const h=await bcrypt.hash(password,12);const u=(await q(`INSERT INTO users(name,email,password_hash,email_verified_at) VALUES($1,$2,$3,CASE WHEN $4::boolean THEN NULL ELSE NOW() END) RETURNING id,name,email,role,is_active,platform_admin,created_at,email_verified_at,session_version,mfa_enabled`,[name,email,h,EMAIL_VERIFICATION_REQUIRED])).rows[0];await createPersonalCompany(u);if(EMAIL_VERIFICATION_REQUIRED){await issueEmailVerification(u,req);await loginEvent(req,email,true,u.id,'register_verification_sent');return res.status(201).json({verification_required:true,email_sent:true,message:'Kayıt tamamlandı. E-posta adresine gönderilen doğrulama bağlantısını aç.'})}const user=await finishLogin(u,req,res,false);res.status(201).json({user})}catch(e){if(e.code==='23505')return res.status(409).json({error:'Bu e-posta zaten kayıtlı'});next(e)}});
app.post('/api/auth/login',async(req,res,next)=>{try{const email=clean(req.body.email).toLowerCase(),password=String(req.body.password||'');if(!emailOk(email)||!password)return res.status(401).json({error:'E-posta veya şifre hatalı'});if(await checkLoginGuard(req,email)){res.setHeader('Retry-After','900');return res.status(429).json({error:'Çok sayıda başarısız deneme nedeniyle giriş 15 dakika kilitlendi'})}const u=(await q('SELECT * FROM users WHERE email=$1',[email])).rows[0],valid=u?await bcrypt.compare(password,u.password_hash):await bcrypt.compare(password,await dummyHashPromise);if(!u||!valid){await loginEvent(req,email,false,u?.id||null,'invalid_credentials');return res.status(401).json({error:'E-posta veya şifre hatalı'})}if(!u.is_active){await loginEvent(req,email,false,u.id,'inactive_account');return res.status(403).json({error:'Hesabınız devre dışı'})}if(EMAIL_VERIFICATION_REQUIRED&&!u.email_verified_at){await loginEvent(req,email,false,u.id,'email_unverified');return res.status(403).json({error:'E-posta adresini doğrulaman gerekli',code:'EMAIL_VERIFICATION_REQUIRED',resend_available:true})}const st=await getSystemSettings();if(st.maintenance_mode===true&&!u.platform_admin){await loginEvent(req,email,false,u.id,'maintenance_mode');return res.status(503).json({error:'Sistem bakım modunda. Platform yöneticileri giriş yapabilir.'})}if(u.mfa_enabled){const ticket=jwt.sign({kind:'mfa-login',id:u.id,sv:Number(u.session_version||0)},JWT_SECRET,{expiresIn:'5m'});return res.json({mfa_required:true,mfa_ticket:ticket,message:'Kimlik doğrulama uygulamandaki 6 haneli kodu gir.'})}const user=await finishLogin(u,req,res,false);res.json({user})}catch(e){next(e)}});
app.post('/api/auth/mfa/verify',async(req,res,next)=>{try{let ticket;try{ticket=jwt.verify(String(req.body.ticket||''),JWT_SECRET)}catch{return res.status(401).json({error:'MFA doğrulama isteğinin süresi dolmuş'})}if(ticket.kind!=='mfa-login')return res.status(401).json({error:'MFA doğrulama isteği geçersiz'});const u=(await q('SELECT * FROM users WHERE id=$1',[ticket.id])).rows[0];if(!u?.is_active||!u.mfa_enabled||Number(ticket.sv)!==Number(u.session_version||0))return res.status(401).json({error:'MFA doğrulama isteği geçersiz'});const code=clean(req.body.code).toUpperCase();let valid=false,recovery=false;if(/^\d{6}$/.test(code)){try{valid=verifyTotp(decryptMfaSecret(u.mfa_secret_cipher),code)}catch{valid=false}}else{const hashes=Array.isArray(u.mfa_recovery_codes)?u.mfa_recovery_codes:[],hash=recoveryHash(code),index=hashes.indexOf(hash);if(index>=0){valid=true;recovery=true;hashes.splice(index,1);await q('UPDATE users SET mfa_recovery_codes=$1::jsonb WHERE id=$2',[JSON.stringify(hashes),u.id])}}if(!valid){await loginEvent(req,u.email,false,u.id,'mfa_invalid');return res.status(401).json({error:'Doğrulama kodu hatalı'})}const user=await finishLogin(u,req,res,true);res.json({user,recovery_code_used:recovery})}catch(e){next(e)}});
app.post('/api/auth/logout',async(req,res)=>{try{const token=jwt.verify(String(req.cookies.dm_token||''),JWT_SECRET);if(token.sid)await q('UPDATE auth_sessions SET revoked_at=NOW() WHERE id=$1 AND user_id=$2',[token.sid,token.id])}catch{}clearCookie(res);res.json({ok:true})});
app.get('/api/auth/me',auth,companyCtx,async(req,res)=>{const u=(await q('SELECT id,name,email,role,is_active,platform_admin,created_at,last_login_at,active_company_id,email_verified_at,mfa_enabled FROM users WHERE id=$1',[req.user.id])).rows[0];if(!u?.is_active)return res.status(403).json({error:'Hesap devre dışı'});res.json({user:{...publicUser(u),created_at:u.created_at,last_login_at:u.last_login_at,active_company_id:u.active_company_id,company:req.company,company_role:req.company.role,mfa_verified:!!req.authSession.mfa_verified,mfa_setup_required:!!(u.platform_admin&&ADMIN_MFA_REQUIRED&&!u.mfa_enabled)}})});
app.post('/api/auth/resend-verification',async(req,res,next)=>{try{const email=clean(req.body.email).toLowerCase();if(emailOk(email)&&mailConfigured()){const u=(await q('SELECT id,name,email,is_active,email_verified_at FROM users WHERE email=$1',[email])).rows[0];if(u?.is_active&&!u.email_verified_at)try{await issueEmailVerification(u,req)}catch(e){console.error('Doğrulama e-postası:',e.message)}}res.json({ok:true,message:'Hesap doğrulanmamışsa yeni bağlantı e-posta adresine gönderildi.'})}catch(e){next(e)}});
app.post('/api/auth/verify-email',async(req,res,next)=>{const token=String(req.body.token||'');if(token.length<32)return res.status(400).json({error:'Doğrulama bağlantısı geçersiz'});const client=await pool.connect();try{await client.query('BEGIN');const row=(await client.query(`SELECT t.id,t.user_id FROM email_verification_tokens t WHERE t.token_hash=$1 AND t.used_at IS NULL AND t.expires_at>NOW() FOR UPDATE`,[resetTokenHash(token)])).rows[0];if(!row){await client.query('ROLLBACK');return res.status(400).json({error:'Doğrulama bağlantısının süresi dolmuş veya daha önce kullanılmış'})}await client.query('UPDATE users SET email_verified_at=COALESCE(email_verified_at,NOW()) WHERE id=$1',[row.user_id]);await client.query('UPDATE email_verification_tokens SET used_at=NOW() WHERE user_id=$1 AND used_at IS NULL',[row.user_id]);await client.query('COMMIT');res.json({ok:true,message:'E-posta adresin doğrulandı. Artık hesabına giriş yapabilirsin.'})}catch(e){await client.query('ROLLBACK').catch(()=>{});next(e)}finally{client.release()}});
app.post('/api/auth/forgot-password',async(req,res,next)=>{try{
 const email=clean(req.body.email).toLowerCase();
 const configured=mailConfigured();
 if(emailOk(email)){
  const u=(await q('SELECT id,name,email,is_active FROM users WHERE email=$1',[email])).rows[0];
  if(u?.is_active&&configured){
   const raw=crypto.randomBytes(32).toString('hex'),hash=resetTokenHash(raw);
   await q('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=$1 AND used_at IS NULL',[u.id]);
   await q("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at,requested_ip) VALUES($1,$2,NOW()+INTERVAL '30 minutes',$3)",[u.id,hash,String(req.ip||'').slice(0,80)]);
   const base=(clean(process.env.PUBLIC_BASE_URL)||`${req.protocol}://${req.get('host')}`).replace(/\/$/,'');
   try{await sendPasswordResetMail(u.email,u.name,`${base}/reset-password.html?token=${encodeURIComponent(raw)}`)}catch(err){console.error('Şifre yenileme e-postası:',err.message)}
  }
 }
 res.json({ok:true,email_enabled:configured,message:configured?'E-posta sistemde kayıtlıysa 30 dakika geçerli şifre yenileme bağlantısı gönderildi.':'Şifre yenileme sayfası hazır; e-posta ile sıfırlama için yönetici RESEND_API_KEY ve PASSWORD_RESET_FROM ayarlarını etkinleştirmeli.'});
}catch(e){next(e)}});
app.get('/api/auth/reset-password/validate',async(req,res,next)=>{try{const hash=resetTokenHash(req.query.token);const r=(await q("SELECT id FROM password_reset_tokens WHERE token_hash=$1 AND used_at IS NULL AND expires_at>NOW()",[hash])).rows[0];res.json({valid:!!r})}catch(e){next(e)}});
app.post('/api/auth/reset-password',async(req,res,next)=>{try{
 const token=String(req.body.token||''),password=String(req.body.password||'');
 if(token.length<32)return res.status(400).json({error:'Şifre yenileme bağlantısı geçersiz'});
 const problem=passwordProblem(password);if(problem)return res.status(400).json({error:problem});
 const hash=resetTokenHash(token),c=await pool.connect();
 try{await c.query('BEGIN');const r=(await c.query("SELECT pr.id,pr.user_id,u.email FROM password_reset_tokens pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=$1 AND pr.used_at IS NULL AND pr.expires_at>NOW() FOR UPDATE",[hash])).rows[0];if(!r){await c.query('ROLLBACK');return res.status(400).json({error:'Bu bağlantının süresi dolmuş veya daha önce kullanılmış'})}const ph=await bcrypt.hash(password,12);await c.query('UPDATE users SET password_hash=$1,session_version=session_version+1 WHERE id=$2',[ph,r.user_id]);await c.query('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=$1 AND used_at IS NULL',[r.user_id]);await c.query('UPDATE auth_sessions SET revoked_at=NOW() WHERE user_id=$1 AND revoked_at IS NULL',[r.user_id]);await c.query('COMMIT');clearCookie(res);await loginEvent(req,r.email,true,r.user_id,'password_reset');res.json({ok:true})}catch(e){await c.query('ROLLBACK').catch(()=>{});throw e}finally{c.release()}
}catch(e){next(e)}});
app.post('/api/account/password',auth,async(req,res,next)=>{try{
 const current=String(req.body.current_password||''),nextPassword=String(req.body.new_password||'');
 const problem=passwordProblem(nextPassword);if(problem)return res.status(400).json({error:problem});
 if(current===nextPassword)return res.status(400).json({error:'Yeni şifre mevcut şifreden farklı olmalı'});
 const u=(await q('SELECT * FROM users WHERE id=$1',[req.user.id])).rows[0];
 if(!u||!(await bcrypt.compare(current,u.password_hash)))return res.status(401).json({error:'Mevcut şifre yanlış'});
 const ph=await bcrypt.hash(nextPassword,12),updated=(await q('UPDATE users SET password_hash=$1,session_version=session_version+1 WHERE id=$2 RETURNING *',[ph,u.id])).rows[0];await q('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=$1 AND used_at IS NULL',[u.id]);await q('UPDATE auth_sessions SET revoked_at=NOW() WHERE user_id=$1 AND revoked_at IS NULL',[u.id]);await issueSession(updated,req,res,!!req.authSession.mfa_verified);await loginEvent(req,u.email,true,u.id,'password_changed');res.json({ok:true,message:'Şifren yenilendi; diğer tüm cihazlardaki oturumlar kapatıldı.'});
}catch(e){next(e)}});
app.get('/api/account/security',auth,async(req,res,next)=>{try{const u=(await q('SELECT email_verified_at,mfa_enabled,platform_admin FROM users WHERE id=$1',[req.user.id])).rows[0];const sessions=(await q(`SELECT id,device_name,ip,last_seen_at,created_at,expires_at,mfa_verified FROM auth_sessions WHERE user_id=$1 AND revoked_at IS NULL AND expires_at>NOW() ORDER BY last_seen_at DESC`,[req.user.id])).rows.map(row=>({...row,current:row.id===req.authSession.id}));res.json({email_verified:!!u.email_verified_at,mfa_enabled:!!u.mfa_enabled,mfa_required:!!(u.platform_admin&&ADMIN_MFA_REQUIRED),sessions})}catch(e){next(e)}});
