app.post('/api/account/mfa/setup',auth,async(req,res,next)=>{try{const password=String(req.body.current_password||''),u=(await q('SELECT * FROM users WHERE id=$1',[req.user.id])).rows[0];if(!u||!(await bcrypt.compare(password,u.password_hash)))return res.status(401).json({error:'Mevcut şifre yanlış'});if(u.mfa_enabled)return res.status(409).json({error:'MFA zaten etkin'});const secret=base32Encode(crypto.randomBytes(20)),cipher=encryptMfaSecret(secret),issuer='Dijital Makinacı',label=encodeURIComponent(`${issuer}:${u.email}`),uri=`otpauth://totp/${label}?secret=${secret}&issuer=${encodeURIComponent(issuer)}&algorithm=SHA1&digits=6&period=30`;await q('UPDATE users SET mfa_secret_cipher=$1 WHERE id=$2',[cipher,u.id]);const qr_data_url=await QRCode.toDataURL(uri,{width:280,margin:1,errorCorrectionLevel:'M'});res.json({secret,otpauth_url:uri,qr_data_url})}catch(e){next(e)}});
app.post('/api/account/mfa/enable',auth,async(req,res,next)=>{try{const u=(await q('SELECT id,mfa_secret_cipher,mfa_enabled FROM users WHERE id=$1',[req.user.id])).rows[0];if(u?.mfa_enabled)return res.status(409).json({error:'MFA zaten etkin'});if(!u?.mfa_secret_cipher)return res.status(400).json({error:'Önce MFA kurulumunu başlat'});let valid=false;try{valid=verifyTotp(decryptMfaSecret(u.mfa_secret_cipher),req.body.code)}catch{}if(!valid)return res.status(400).json({error:'Doğrulama kodu hatalı'});const codes=makeRecoveryCodes(),hashes=codes.map(recoveryHash);await q('UPDATE users SET mfa_enabled=true,mfa_recovery_codes=$1::jsonb WHERE id=$2',[JSON.stringify(hashes),u.id]);await q('UPDATE auth_sessions SET mfa_verified=true WHERE id=$1 AND user_id=$2',[req.authSession.id,u.id]);res.json({ok:true,recovery_codes:codes,message:'MFA etkinleştirildi. Kurtarma kodlarını güvenli bir yerde sakla.'})}catch(e){next(e)}});
app.post('/api/account/mfa/recovery-codes',auth,async(req,res,next)=>{try{const password=String(req.body.current_password||''),u=(await q('SELECT id,password_hash,mfa_enabled FROM users WHERE id=$1',[req.user.id])).rows[0];if(!u?.mfa_enabled)return res.status(400).json({error:'MFA etkin değil'});if(!(await bcrypt.compare(password,u.password_hash)))return res.status(401).json({error:'Mevcut şifre yanlış'});const codes=makeRecoveryCodes();await q('UPDATE users SET mfa_recovery_codes=$1::jsonb WHERE id=$2',[JSON.stringify(codes.map(recoveryHash)),u.id]);res.json({ok:true,recovery_codes:codes})}catch(e){next(e)}});
app.post('/api/account/mfa/disable',auth,async(req,res,next)=>{try{if(req.user.platform_admin&&ADMIN_MFA_REQUIRED)return res.status(403).json({error:'Platform yöneticilerinde MFA zorunludur'});const password=String(req.body.current_password||''),u=(await q('SELECT * FROM users WHERE id=$1',[req.user.id])).rows[0];if(!u?.mfa_enabled)return res.status(400).json({error:'MFA etkin değil'});if(!(await bcrypt.compare(password,u.password_hash)))return res.status(401).json({error:'Mevcut şifre yanlış'});let valid=false;try{valid=verifyTotp(decryptMfaSecret(u.mfa_secret_cipher),req.body.code)}catch{}if(!valid)return res.status(400).json({error:'Doğrulama kodu hatalı'});await q("UPDATE users SET mfa_enabled=false,mfa_secret_cipher=NULL,mfa_recovery_codes='[]'::jsonb,session_version=session_version+1 WHERE id=$1",[u.id]);await q('UPDATE auth_sessions SET revoked_at=NOW() WHERE user_id=$1 AND revoked_at IS NULL',[u.id]);clearCookie(res);res.json({ok:true,relogin:true})}catch(e){next(e)}});
