app.get('/api/search',auth,companyCtx,async(req,res,next)=>{try{const term=clean(req.query.q).slice(0,100);if(term.length<2)return res.json({items:[],page:1,limit:20,total:0});const page=Math.max(1,Math.round(num(req.query.page,1))),limit=Math.min(50,Math.max(5,Math.round(num(req.query.limit,20)))),offset=(page-1)*limit,pattern=`%${term}%`;const rows=(await q(`WITH results AS (
 SELECT 'machine' type,m.id,m.name title,CONCAT_WS(' • ',m.manufacturer,m.model,m.serial_no) subtitle,NULL::text slug,m.created_at sort_date FROM machines m WHERE m.company_id=$1 AND m.archived_at IS NULL AND CONCAT_WS(' ',m.name,m.manufacturer,m.model,m.serial_no,m.location) ILIKE $2
 UNION ALL SELECT 'maintenance',ma.id,ma.task,CONCAT_WS(' • ',mx.name,ma.maintenance_type,ma.due_date::text),NULL,ma.created_at FROM maintenance ma LEFT JOIN machines mx ON mx.id=ma.machine_id WHERE ma.company_id=$1 AND ma.archived_at IS NULL AND CONCAT_WS(' ',ma.task,mx.name,ma.note) ILIKE $2
 UNION ALL SELECT 'work_order',w.id,w.title,CONCAT_WS(' • ',mw.name,uw.name,w.status),NULL,w.created_at FROM work_orders w LEFT JOIN machines mw ON mw.id=w.machine_id LEFT JOIN users uw ON uw.id=w.assigned_user_id WHERE w.company_id=$1 AND w.archived_at IS NULL AND CONCAT_WS(' ',w.title,w.description,mw.name,uw.name) ILIKE $2
 UNION ALL SELECT 'fault',f.id,f.symptom,CONCAT_WS(' • ',mf.name,f.severity,f.system),NULL,f.created_at FROM faults f LEFT JOIN machines mf ON mf.id=f.machine_id WHERE f.company_id=$1 AND CONCAT_WS(' ',f.symptom,f.note,f.diagnosis,mf.name) ILIKE $2
 UNION ALL SELECT 'part',p.id,p.name,CONCAT_WS(' • ',p.part_code,p.category,p.location),NULL,p.created_at FROM parts p WHERE p.company_id=$1 AND CONCAT_WS(' ',p.name,p.part_code,p.category,p.location,p.supplier) ILIKE $2
 UNION ALL SELECT 'article',a.id,a.title,CONCAT_WS(' • ',a.category,a.standard),a.slug,a.updated_at FROM knowledge_articles a WHERE a.is_published=true AND CONCAT_WS(' ',a.title,a.summary,a.body,a.standard) ILIKE $2
 ) SELECT *,COUNT(*) OVER()::int total FROM results ORDER BY sort_date DESC LIMIT $3 OFFSET $4`,[req.company.id,pattern,limit,offset])).rows;res.json({items:rows.map(({total,...row})=>row),page,limit,total:rows[0]?.total||0})}catch(e){next(e)}});
