const machineStats=`(SELECT COUNT(*) FROM faults f WHERE f.machine_id=m.id AND f.company_id=m.company_id AND f.status='open')::int open_faults,(SELECT COUNT(*) FROM faults f WHERE f.machine_id=m.id AND f.company_id=m.company_id AND f.status='open' AND f.severity='Kritik')::int critical_faults,(SELECT COUNT(*) FROM faults f WHERE f.machine_id=m.id AND f.company_id=m.company_id AND f.created_at>=NOW()-INTERVAL '90 days')::int faults90,(SELECT COUNT(*) FROM maintenance x WHERE x.machine_id=m.id AND x.company_id=m.company_id AND x.archived_at IS NULL AND x.status='open' AND x.due_date<CURRENT_DATE)::int overdue_maintenance,(SELECT COUNT(*) FROM maintenance x WHERE x.machine_id=m.id AND x.company_id=m.company_id AND x.archived_at IS NULL AND x.status='open' AND x.due_date BETWEEN CURRENT_DATE AND CURRENT_DATE+30)::int due30`;
