app.get('/api/faults',auth,companyCtx,async(req,res)=>res.json((await q(`SELECT f.*,x.name machine_name,u.name created_by_name FROM faults f LEFT JOIN machines x ON x.id=f.machine_id LEFT JOIN users u ON u.id=f.user_id WHERE f.company_id=$1 ORDER BY CASE WHEN f.status='open' THEN 0 ELSE 1 END,f.id DESC LIMIT 400`,[req.company.id])).rows));
app.post('/api/faults',auth,companyCtx,permit('owner','manager','technician','operator'),async(req,res)=>{const b=req.body,key=idempotencyKey(req);if(key){const existing=(await q('SELECT * FROM faults WHERE company_id=$1 AND client_request_id=$2',[req.company.id,key])).rows[0];if(existing)return res.json(existing)}if(!clean(b.symptom))return res.status(400).json({error:'Belirti gerekli'});if(b.machine_id&&!(await ownMachine(b.machine_id,req.company.id)))return res.status(403).json({error:'Makine aktif firmaya ait değil'});const r=await q(`INSERT INTO faults(user_id,company_id,machine_id,system,symptom,measurements,note,diagnosis,severity,root_cause,action_taken,downtime_min,client_request_id) VALUES($1,$2,$3,$4,$5,$6::jsonb,$7,$8,$9,$10,$11,$12,$13) RETURNING *`,[req.user.id,req.company.id,b.machine_id||null,clean(b.system),clean(b.symptom),JSON.stringify(b.measurements||{}),clean(b.note),clean(b.diagnosis),clean(b.severity)||'Orta',clean(b.root_cause),clean(b.action_taken),Math.max(0,Math.round(num(b.downtime_min))),key]);await audit(req,'create','fault',r.rows[0].id,{symptom:r.rows[0].symptom,severity:r.rows[0].severity});res.status(201).json(r.rows[0])});
app.patch('/api/faults/:id/status',auth,companyCtx,permit('owner','manager','technician'),async(req,res)=>{const st=req.body.status==='closed'?'closed':'open';const r=await q(`UPDATE faults SET status=$1,root_cause=COALESCE($2,root_cause),action_taken=COALESCE($3,action_taken),downtime_min=COALESCE($4,downtime_min),closed_at=CASE WHEN $1='closed' THEN NOW() ELSE NULL END WHERE id=$5 AND company_id=$6 RETURNING *`,[st,req.body.root_cause??null,req.body.action_taken??null,req.body.downtime_min===undefined?null:Math.round(num(req.body.downtime_min)),req.params.id,req.company.id]);if(!r.rows[0])return res.status(404).json({error:'Arıza kaydı bulunamadı'});await audit(req,st==='closed'?'close':'reopen','fault',req.params.id,{symptom:r.rows[0].symptom});res.json(r.rows[0])});
app.delete('/api/faults/:id',auth,companyCtx,permit('owner','manager'),async(req,res)=>{const r=await q('DELETE FROM faults WHERE id=$1 AND company_id=$2 RETURNING id,symptom',[req.params.id,req.company.id]);if(r.rows[0])await audit(req,'delete','fault',r.rows[0].id,{symptom:r.rows[0].symptom});res.json({ok:true})});

