const allowedMime=new Set(['image/jpeg','image/png','image/webp','application/pdf','text/plain','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']);
function fileMatchesMime(file){const b=file.buffer||Buffer.alloc(0),hex=b.subarray(0,12).toString('hex');if(file.mimetype==='image/jpeg')return hex.startsWith('ffd8ff');if(file.mimetype==='image/png')return hex.startsWith('89504e470d0a1a0a');if(file.mimetype==='image/webp')return b.subarray(0,4).toString()==='RIFF'&&b.subarray(8,12).toString()==='WEBP';if(file.mimetype==='application/pdf')return b.subarray(0,5).toString()==='%PDF-';if(file.mimetype==='application/msword')return hex.startsWith('d0cf11e0a1b11ae1');if(file.mimetype==='application/vnd.openxmlformats-officedocument.wordprocessingml.document')return hex.startsWith('504b0304');if(file.mimetype==='text/plain')return !b.subarray(0,4096).includes(0);return false}
async function persistAttachment(req,refs,context){const settings=await getSystemSettings();if(settings.allow_file_uploads===false){const error=Error('Dosya yükleme platform yöneticisi tarafından kapatıldı');error.status=403;throw error}if(!storage.configured){const error=Error('Object storage yapılandırılmadan yeni dosya yüklenemez');error.status=503;throw error}if(!req.file){const error=Error('Dosya seçilmedi');error.status=400;throw error}if(!allowedMime.has(req.file.mimetype)||!fileMatchesMime(req.file)){const error=Error('Dosya içeriği desteklenen türle eşleşmiyor');error.status=415;throw error}const fileName=clean(path.basename(req.file.originalname)).slice(0,240)||'dosya',key=storage.objectKey({companyId:req.company.id,context,fileName}),checksum=crypto.createHash('sha256').update(req.file.buffer).digest('hex'),uploaded=await storage.put({key,body:req.file.buffer,contentType:req.file.mimetype,metadata:{company:String(req.company.id),checksum}});try{return (await q(`INSERT INTO attachments(user_id,company_id,machine_id,maintenance_id,work_order_id,file_name,mime_type,size_bytes,file_data,caption,storage_key,storage_bucket,storage_etag,checksum_sha256) VALUES($1,$2,$3,$4,$5,$6,$7,$8,NULL,$9,$10,$11,$12,$13) RETURNING id,file_name,mime_type,size_bytes,caption,created_at`,[req.user.id,req.company.id,refs.machine_id||null,refs.maintenance_id||null,refs.work_order_id||null,fileName,req.file.mimetype,req.file.size,clean(req.body.caption).slice(0,240),uploaded.key,uploaded.bucket,uploaded.etag,checksum])).rows[0]}catch(error){await storage.remove(uploaded.key).catch(()=>{});throw error}}
function uploadError(error,res,next){if(error.status)return res.status(error.status).json({error:error.message});next(error)}
app.post('/api/machines/:id/attachments',auth,companyCtx,permit('owner','manager','technician','operator'),upload.single('file'),async(req,res,next)=>{try{if(!(await ownMachine(req.params.id,req.company.id)))return res.status(404).json({error:'Aktif makine bulunamadı'});const row=await persistAttachment(req,{machine_id:req.params.id},'machines');await audit(req,'create','attachment',row.id,{file_name:row.file_name,machine_id:req.params.id});res.status(201).json(row)}catch(e){uploadError(e,res,next)}});
app.post('/api/work-orders/:id/attachments',auth,companyCtx,permit('owner','manager','technician','operator'),upload.single('file'),async(req,res,next)=>{try{const order=await ownOperationalParent('work_order',req.params.id,req.company.id);if(!order)return res.status(404).json({error:'İş emri bulunamadı'});const row=await persistAttachment(req,{machine_id:order.machine_id,work_order_id:order.id},'work-orders');await q(`INSERT INTO work_order_events(company_id,work_order_id,user_id,event_type,body,details) VALUES($1,$2,$3,'attachment','Dosya eklendi',$4::jsonb)`,[req.company.id,order.id,req.user.id,JSON.stringify({attachment_id:row.id,file_name:row.file_name})]);res.status(201).json(row)}catch(e){uploadError(e,res,next)}});
app.post('/api/checklists/items/:id/photo',auth,companyCtx,permit('owner','manager','technician','operator'),upload.single('file'),async(req,res,next)=>{try{const item=(await q('SELECT * FROM checklist_items WHERE id=$1 AND company_id=$2',[req.params.id,req.company.id])).rows[0];if(!item)return res.status(404).json({error:'Checklist maddesi bulunamadı'});if(!req.file?.mimetype.startsWith('image/'))return res.status(415).json({error:'Checklist kanıtı fotoğraf olmalı'});const parent=await ownOperationalParent(item.parent_type,item.parent_id,req.company.id),refs={machine_id:parent?.machine_id||null,maintenance_id:item.parent_type==='maintenance'?item.parent_id:null,work_order_id:item.parent_type==='work_order'?item.parent_id:null};const row=await persistAttachment(req,refs,'checklists');await q('UPDATE checklist_items SET photo_attachment_id=$1 WHERE id=$2',[row.id,item.id]);res.status(201).json(row)}catch(e){uploadError(e,res,next)}});
app.post('/api/company/logo',auth,companyCtx,permit('owner','manager'),upload.single('file'),async(req,res,next)=>{try{if(!req.file?.mimetype.startsWith('image/'))return res.status(415).json({error:'Firma logosu PNG, JPEG veya WebP olmalı'});const row=await persistAttachment(req,{},'company-logo');await q('UPDATE companies SET logo_attachment_id=$1 WHERE id=$2',[row.id,req.company.id]);res.status(201).json(row)}catch(e){uploadError(e,res,next)}});
app.get('/api/attachments/:id',auth,companyCtx,async(req,res,next)=>{try{const attachment=(await q('SELECT file_name,mime_type,file_data,storage_key,storage_etag FROM attachments WHERE id=$1 AND company_id=$2',[req.params.id,req.company.id])).rows[0];if(!attachment)return res.status(404).end();let body=attachment.file_data;if(attachment.storage_key){const object=await storage.get(attachment.storage_key);body=object.body;if(object.etag)res.setHeader('ETag',`"${object.etag}"`)}if(!body)return res.status(410).json({error:'Dosya içeriği storage içinde bulunamadı'});res.setHeader('Content-Type',attachment.mime_type);res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(attachment.file_name)}`);res.setHeader('Cache-Control','private, max-age=300');res.send(body)}catch(e){next(e)}});
app.delete('/api/attachments/:id',auth,companyCtx,permit('owner','manager','technician'),async(req,res,next)=>{try{const attachment=(await q('SELECT id,storage_key FROM attachments WHERE id=$1 AND company_id=$2',[req.params.id,req.company.id])).rows[0];if(!attachment)return res.status(404).json({error:'Dosya bulunamadı'});if(attachment.storage_key)await storage.remove(attachment.storage_key);await q('DELETE FROM attachments WHERE id=$1',[attachment.id]);res.json({ok:true})}catch(e){next(e)}});
app.get('/api/machines/:id/qr',auth,companyCtx,async(req,res)=>{const m=(await q('SELECT id,name FROM machines WHERE id=$1 AND company_id=$2',[req.params.id,req.company.id])).rows[0];if(!m)return res.status(404).json({error:'Makine bulunamadı'});const base=`${req.protocol}://${req.get('host')}`,url=`${base}/app?machine=${m.id}`;const svg=await QRCode.toString(url,{type:'svg',margin:1,width:360,errorCorrectionLevel:'M'});res.type('image/svg+xml').send(svg)});

