app.get('/api/calendar',auth,companyCtx,async(req,res)=>{const month=validDateMonth(req.query.month);const [y,m]=month.split('-').map(Number),start=`${month}-01`,next=m===12?`${y+1}-01-01`:`${y}-${String(m+1).padStart(2,'0')}-01`;const [ma,wo]=await Promise.all([q(`SELECT ma.id,ma.task title,ma.due_date date,ma.status,ma.priority,ma.maintenance_type type,x.name machine_name,'maintenance' kind FROM maintenance ma LEFT JOIN machines x ON x.id=ma.machine_id WHERE ma.company_id=$1 AND ma.archived_at IS NULL AND ma.due_date >= $2::date AND ma.due_date < $3::date ORDER BY ma.due_date`,[req.company.id,start,next]),q(`SELECT w.id,w.title,w.due_date date,w.status,w.priority,'İş Emri' type,m.name machine_name,'work' kind FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id WHERE w.company_id=$1 AND w.due_date >= $2::date AND w.due_date < $3::date ORDER BY w.due_date`,[req.company.id,start,next])]);res.json({month,events:[...ma.rows,...wo.rows].sort((a,b)=>String(a.date).localeCompare(String(b.date)))})});

// ADVANCED FAULT ANALYTICS
app.get('/api/analytics/faults',auth,companyCtx,async(req,res)=>{const days=Math.min(730,Math.max(7,Math.round(num(req.query.days,90))));const params=[req.company.id,days];const [sum,systems,severity,recurrent,machinesR,roots,trend]=await Promise.all([
 q(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status='open')::int open,COUNT(*) FILTER(WHERE status='closed')::int closed,COALESCE(SUM(downtime_min),0)::int downtime_min,COALESCE(ROUND(AVG(downtime_min) FILTER(WHERE status='closed')),0)::int avg_downtime_min,COALESCE(ROUND(AVG(EXTRACT(EPOCH FROM(closed_at-created_at))/60) FILTER(WHERE closed_at IS NOT NULL)),0)::int mttr_min FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int)`,params),
 q(`SELECT COALESCE(NULLIF(system,''),'Diğer') label,COUNT(*)::int value FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) GROUP BY 1 ORDER BY value DESC LIMIT 12`,params),
 q(`SELECT COALESCE(NULLIF(severity,''),'Orta') label,COUNT(*)::int value FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) GROUP BY 1 ORDER BY value DESC`,params),
 q(`SELECT symptom label,COUNT(*)::int value,COALESCE(SUM(downtime_min),0)::int downtime_min FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) GROUP BY symptom HAVING COUNT(*)>1 ORDER BY value DESC,downtime_min DESC LIMIT 10`,params),
 q(`SELECT COALESCE(m.name,'Makine seçilmedi') label,COUNT(*)::int value,COALESCE(SUM(f.downtime_min),0)::int downtime_min FROM faults f LEFT JOIN machines m ON m.id=f.machine_id WHERE f.company_id=$1 AND f.created_at>=NOW()-make_interval(days=>$2::int) GROUP BY m.name ORDER BY value DESC,downtime_min DESC LIMIT 10`,params),
 q(`SELECT root_cause label,COUNT(*)::int value FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) AND NULLIF(TRIM(root_cause),'') IS NOT NULL GROUP BY root_cause ORDER BY value DESC LIMIT 10`,params),
 q(`SELECT to_char(date_trunc('month',created_at),'YYYY-MM') month,COUNT(*)::int value,COALESCE(SUM(downtime_min),0)::int downtime_min FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) GROUP BY 1 ORDER BY 1`,params)
]);res.json({days,summary:sum.rows[0],systems:systems.rows,severity:severity.rows,recurrent:recurrent.rows,machines:machinesR.rows,rootCauses:roots.rows,trend:trend.rows})});

