async function serviceReportData(type,id,req){const maintenanceReport=type==='maintenance',record=(await q(maintenanceReport?`SELECT ma.*,m.name machine_name,m.manufacturer,m.model,m.serial_no,m.location,c.name company_name,c.logo_attachment_id company_logo_attachment_id,u.name created_by_name,t.name technician_member_name FROM maintenance ma LEFT JOIN machines m ON m.id=ma.machine_id LEFT JOIN companies c ON c.id=ma.company_id LEFT JOIN users u ON u.id=ma.user_id LEFT JOIN users t ON t.id=ma.technician_user_id WHERE ma.id=$1 AND ma.company_id=$2`:`SELECT w.*,m.name machine_name,m.manufacturer,m.model,m.serial_no,m.location,c.name company_name,c.logo_attachment_id company_logo_attachment_id,u.name created_by_name,t.name assigned_member_name,a.name approved_by_name FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id LEFT JOIN companies c ON c.id=w.company_id LEFT JOIN users u ON u.id=w.user_id LEFT JOIN users t ON t.id=w.assigned_user_id LEFT JOIN users a ON a.id=w.approved_by WHERE w.id=$1 AND w.company_id=$2`,[id,req.company.id])).rows[0];if(!record)return null;const parentType=maintenanceReport?'maintenance':'work_order',column=maintenanceReport?'maintenance_id':'work_order_id',[checklist,partsUsed,attachments,signatures,measurements]=await Promise.all([q(`SELECT c.*,u.name completed_by_name FROM checklist_items c LEFT JOIN users u ON u.id=c.completed_by WHERE c.company_id=$1 AND c.parent_type=$2 AND c.parent_id=$3 ORDER BY c.position,c.id`,[req.company.id,parentType,id]),q(`SELECT pu.*,p.name part_name,p.part_code,p.unit FROM part_usages pu JOIN parts p ON p.id=pu.part_id WHERE pu.company_id=$1 AND pu.${column}=$2 ORDER BY pu.id`,[req.company.id,id]),q(`SELECT id,file_name,mime_type,size_bytes,caption,created_at FROM attachments WHERE company_id=$1 AND ${column}=$2 ORDER BY id`,[req.company.id,id]),q(`SELECT signer_type,signer_name,signature_data,signed_at FROM report_signatures WHERE company_id=$1 AND parent_type=$2 AND parent_id=$3`,[req.company.id,parentType,id]),record.machine_id?q(`SELECT * FROM machine_measurements WHERE company_id=$1 AND machine_id=$2 ORDER BY measured_at DESC LIMIT 6`,[req.company.id,record.machine_id]):Promise.resolve({rows:[]})]);const reportNo=`SRV-${maintenanceReport?'B':'I'}-${String(record.id).padStart(6,'0')}`,base=(clean(process.env.PUBLIC_BASE_URL)||`${req.protocol}://${req.get('host')}`).replace(/\/$/,''),qrDataUrl=await QRCode.toDataURL(`${base}/reports/${maintenanceReport?'maintenance':'work-order'}/${record.id}`,{width:180,margin:1,errorCorrectionLevel:'M'});return {type:parentType,report_no:reportNo,record,company_logo_attachment_id:record.company_logo_attachment_id||null,checklist:checklist.rows,parts:partsUsed.rows,attachments:attachments.rows,signatures:signatures.rows,measurements:measurements.rows,qr_data_url:qrDataUrl,generated_at:new Date().toISOString(),generated_by:req.user.name}}
app.get('/api/reports/maintenance/:id',auth,companyCtx,async(req,res,next)=>{try{const data=await serviceReportData('maintenance',req.params.id,req);if(!data)return res.status(404).json({error:'Bakım kaydı bulunamadı'});res.json(data)}catch(e){next(e)}});
