app.post('/api/reports/:parentType/:id/signatures',auth,companyCtx,permit('owner','manager','technician'),async(req,res,next)=>{try{const type=req.params.parentType==='maintenance'?'maintenance':req.params.parentType==='work-order'||req.params.parentType==='work_order'?'work_order':null,signerType=['technician','customer'].includes(req.body.signer_type)?req.body.signer_type:null,signerName=clean(req.body.signer_name).slice(0,160),signatureData=String(req.body.signature_data||'');if(!type||!signerType)return res.status(400).json({error:'İmza türü geçersiz'});if(!await ownOperationalParent(type,req.params.id,req.company.id))return res.status(404).json({error:'İlgili kayıt bulunamadı'});if(!signerName)return res.status(400).json({error:'İmzalayan kişinin adı gerekli'});if(!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(signatureData)||signatureData.length>400000)return res.status(400).json({error:'İmza verisi geçersiz veya çok büyük'});const row=(await q(`INSERT INTO report_signatures(company_id,parent_type,parent_id,signer_type,signer_name,signature_data,signed_by) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(company_id,parent_type,parent_id,signer_type) DO UPDATE SET signer_name=EXCLUDED.signer_name,signature_data=EXCLUDED.signature_data,signed_by=EXCLUDED.signed_by,signed_at=NOW() RETURNING signer_type,signer_name,signed_at`,[req.company.id,type,req.params.id,signerType,signerName,signatureData,req.user.id])).rows[0];await audit(req,'signature','report',req.params.id,{parent_type:type,signer_type:signerType});res.json(row)}catch(e){next(e)}});

