app.get('/api/dashboard',auth,companyCtx,async(req,res)=>{const c=req.company.id;const [m,ma,f,od,d30,done,crit,low,cost,rm,rf,wo]=await Promise.all([q('SELECT COUNT(*)::int c FROM machines WHERE company_id=$1 AND archived_at IS NULL',[c]),q("SELECT COUNT(*)::int c FROM maintenance WHERE company_id=$1 AND archived_at IS NULL AND status='open'",[c]),q("SELECT COUNT(*)::int c FROM faults WHERE company_id=$1 AND status='open'",[c]),q("SELECT COUNT(*)::int c FROM maintenance WHERE company_id=$1 AND archived_at IS NULL AND status='open' AND due_date<CURRENT_DATE",[c]),q("SELECT COUNT(*)::int c FROM maintenance WHERE company_id=$1 AND archived_at IS NULL AND status='open' AND due_date BETWEEN CURRENT_DATE AND CURRENT_DATE+30",[c]),q("SELECT COUNT(*)::int c FROM maintenance WHERE company_id=$1 AND archived_at IS NULL AND status='done' AND completed_at>=date_trunc('month',NOW())",[c]),q("SELECT COUNT(*)::int c FROM machines WHERE company_id=$1 AND archived_at IS NULL AND (criticality='Kritik' OR status IN ('Arızalı','Bakımda'))",[c]),q('SELECT COUNT(*)::int c FROM parts WHERE company_id=$1 AND quantity<=min_quantity',[c]),q("SELECT COALESCE(SUM(cost),0)::numeric t FROM maintenance WHERE company_id=$1 AND archived_at IS NULL AND completed_at>=date_trunc('month',NOW())",[c]),q(`SELECT ma.id,ma.task,ma.due_date,ma.status,ma.priority,x.name machine_name FROM maintenance ma LEFT JOIN machines x ON x.id=ma.machine_id WHERE ma.company_id=$1 AND ma.archived_at IS NULL ORDER BY ma.created_at DESC LIMIT 6`,[c]),q(`SELECT f.id,f.symptom,f.status,f.severity,f.created_at,x.name machine_name FROM faults f LEFT JOIN machines x ON x.id=f.machine_id WHERE f.company_id=$1 ORDER BY f.created_at DESC LIMIT 6`,[c]),q("SELECT COUNT(*)::int c FROM work_orders WHERE company_id=$1 AND status<>'done'",[c])]);const ms=await q(`SELECT m.*,${machineStats} FROM machines m WHERE m.company_id=$1 AND m.archived_at IS NULL`,[c]);const scores=ms.rows.map(healthScore),avgHealth=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0;res.json({machines:m.rows[0].c,maintenance:ma.rows[0].c,faults:f.rows[0].c,overdue:od.rows[0].c,due30:d30.rows[0].c,doneMonth:done.rows[0].c,critical:crit.rows[0].c,lowStock:low.rows[0].c,costMonth:Number(cost.rows[0].t||0),openWorkOrders:wo.rows[0].c,avgHealth,recentMaintenance:rm.rows,recentFaults:rf.rows,company:req.company})});

