app.patch('/api/admin/users/:id/role',auth,siteAdmin,async(req,res,next)=>{try{const on=req.body.role==='admin';if(Number(req.params.id)===Number(req.user.id)&&!on)return res.status(400).json({error:'Kendi platform admin yetkinizi kaldıramazsınız'});const r=await q(`UPDATE users SET platform_admin=$1,role=CASE WHEN $1 THEN 'admin' ELSE 'user' END WHERE id=$2 RETURNING id,name,email,role,platform_admin,is_active`,[on,req.params.id]);if(r.rows[0])await adminAudit(req,on?'platform_admin_granted':'platform_admin_revoked','user',req.params.id,{email:r.rows[0].email});res.json(r.rows[0]||{})}catch(e){next(e)}});
app.delete('/api/admin/users/:id',auth,siteAdmin,async(req,res,next)=>{try{if(Number(req.params.id)===Number(req.user.id))return res.status(400).json({error:'Kendi platform admin hesabınızı silemezsiniz'});const u=(await q(`SELECT u.email,u.platform_admin,(SELECT COUNT(*) FROM machines WHERE user_id=u.id)::int machines,(SELECT COUNT(*) FROM maintenance WHERE user_id=u.id)::int maintenance,(SELECT COUNT(*) FROM faults WHERE user_id=u.id)::int faults,(SELECT COUNT(*) FROM parts WHERE user_id=u.id)::int parts,(SELECT COUNT(*) FROM companies WHERE owner_user_id=u.id)::int owned_companies FROM users u WHERE u.id=$1`,[req.params.id])).rows[0];if(!u)return res.status(404).json({error:'Kullanıcı bulunamadı'});const deps=num(u.machines)+num(u.maintenance)+num(u.faults)+num(u.parts)+num(u.owned_companies);if(deps>0)return res.status(409).json({error:'Bu kullanıcının operasyon kayıtları veya sahip olduğu firma var. Veri kaybını önlemek için hesabı silmek yerine pasifleştir.'});await q('DELETE FROM users WHERE id=$1',[req.params.id]);await adminAudit(req,'user_deleted','user',req.params.id,{email:u.email,was_platform_admin:u.platform_admin});res.json({ok:true})}catch(e){next(e)}});

app.get('/api/admin/companies',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`;res.json((await q(`SELECT c.id,c.name,c.code,c.created_at,u.name owner_name,u.email owner_email,(SELECT COUNT(*) FROM company_members cm WHERE cm.company_id=c.id AND cm.is_active)::int members,(SELECT COUNT(*) FROM machines m WHERE m.company_id=c.id)::int machines,(SELECT COUNT(*) FROM faults f WHERE f.company_id=c.id AND f.status='open')::int open_faults,(SELECT COUNT(*) FROM maintenance ma WHERE ma.company_id=c.id AND ma.status='open')::int open_maintenance,(SELECT COUNT(*) FROM work_orders w WHERE w.company_id=c.id AND w.status<>'done')::int open_work_orders FROM companies c LEFT JOIN users u ON u.id=c.owner_user_id WHERE ($1='%%' OR c.name ILIKE $1 OR c.code ILIKE $1 OR u.email ILIKE $1) ORDER BY c.id DESC LIMIT 500`,[term])).rows)}catch(e){next(e)}});
app.get('/api/admin/companies/:id',auth,siteAdmin,async(req,res,next)=>{try{const c=(await q(`SELECT c.*,u.name owner_name,u.email owner_email FROM companies c LEFT JOIN users u ON u.id=c.owner_user_id WHERE c.id=$1`,[req.params.id])).rows[0];if(!c)return res.status(404).json({error:'Firma bulunamadı'});const [members,machinesR,faultsR,maintR,workR]=await Promise.all([q(`SELECT u.id,u.name,u.email,cm.role,cm.is_active FROM company_members cm JOIN users u ON u.id=cm.user_id WHERE cm.company_id=$1 ORDER BY cm.id`,[c.id]),q('SELECT id,name,manufacturer,model,status,criticality FROM machines WHERE company_id=$1 ORDER BY id DESC LIMIT 100',[c.id]),q(`SELECT f.id,f.symptom,f.severity,f.status,m.name machine_name,f.created_at FROM faults f LEFT JOIN machines m ON m.id=f.machine_id WHERE f.company_id=$1 ORDER BY f.id DESC LIMIT 50`,[c.id]),q(`SELECT ma.id,ma.task,ma.status,ma.due_date,m.name machine_name FROM maintenance ma LEFT JOIN machines m ON m.id=ma.machine_id WHERE ma.company_id=$1 ORDER BY ma.id DESC LIMIT 50`,[c.id]),q(`SELECT w.id,w.title,w.status,w.priority,w.due_date,m.name machine_name FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id WHERE w.company_id=$1 ORDER BY w.id DESC LIMIT 50`,[c.id])]);res.json({company:c,members:members.rows,machines:machinesR.rows,faults:faultsR.rows,maintenance:maintR.rows,workOrders:workR.rows})}catch(e){next(e)}});
app.patch('/api/admin/companies/:id',auth,siteAdmin,async(req,res,next)=>{try{const name=clean(req.body.name);if(name.length<2)return res.status(400).json({error:'Firma adı gerekli'});const r=(await q('UPDATE companies SET name=$1 WHERE id=$2 RETURNING id,name,code',[name,req.params.id])).rows[0];if(!r)return res.status(404).json({error:'Firma bulunamadı'});await adminAudit(req,'company_renamed','company',req.params.id,{name});res.json(r)}catch(e){next(e)}});

app.get('/api/admin/machines',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`,status=clean(req.query.status);res.json((await q(`SELECT m.id,m.name,m.manufacturer,m.model,m.serial_no,m.status,m.criticality,m.hours,m.created_at,c.name company_name,u.name created_by,(SELECT COUNT(*) FROM faults f WHERE f.machine_id=m.id AND f.status='open')::int open_faults,(SELECT COUNT(*) FROM maintenance ma WHERE ma.machine_id=m.id AND ma.status='open' AND ma.due_date<CURRENT_DATE)::int overdue FROM machines m LEFT JOIN companies c ON c.id=m.company_id LEFT JOIN users u ON u.id=m.user_id WHERE ($1='%%' OR m.name ILIKE $1 OR m.manufacturer ILIKE $1 OR m.model ILIKE $1 OR m.serial_no ILIKE $1 OR c.name ILIKE $1) AND ($2='' OR m.status=$2) ORDER BY m.id DESC LIMIT 700`,[term,status])).rows)}catch(e){next(e)}});
app.get('/api/admin/faults',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`,status=clean(req.query.status),severity=clean(req.query.severity);res.json((await q(`SELECT f.id,f.symptom,f.system,f.severity,f.status,f.root_cause,f.downtime_min,f.created_at,f.closed_at,m.name machine_name,c.name company_name,u.name created_by FROM faults f LEFT JOIN machines m ON m.id=f.machine_id LEFT JOIN companies c ON c.id=f.company_id LEFT JOIN users u ON u.id=f.user_id WHERE ($1='%%' OR f.symptom ILIKE $1 OR f.system ILIKE $1 OR m.name ILIKE $1 OR c.name ILIKE $1) AND ($2='' OR f.status=$2) AND ($3='' OR f.severity=$3) ORDER BY CASE f.severity WHEN 'Kritik' THEN 0 WHEN 'Yüksek' THEN 1 ELSE 2 END,f.id DESC LIMIT 700`,[term,status,severity])).rows)}catch(e){next(e)}});
app.get('/api/admin/maintenance',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`,status=clean(req.query.status);res.json((await q(`SELECT ma.id,ma.task,ma.maintenance_type,ma.priority,ma.status,ma.due_date,ma.completed_at,ma.cost,ma.duration_min,m.name machine_name,c.name company_name,u.name created_by FROM maintenance ma LEFT JOIN machines m ON m.id=ma.machine_id LEFT JOIN companies c ON c.id=ma.company_id LEFT JOIN users u ON u.id=ma.user_id WHERE ($1='%%' OR ma.task ILIKE $1 OR m.name ILIKE $1 OR c.name ILIKE $1) AND ($2='' OR ma.status=$2) ORDER BY ma.id DESC LIMIT 700`,[term,status])).rows)}catch(e){next(e)}});
app.get('/api/admin/work-orders',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`,status=clean(req.query.status);res.json((await q(`SELECT w.id,w.title,w.priority,w.status,w.assigned_to,w.due_date,w.cost,w.downtime_min,w.created_at,m.name machine_name,c.name company_name,u.name created_by FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id LEFT JOIN companies c ON c.id=w.company_id LEFT JOIN users u ON u.id=w.user_id WHERE ($1='%%' OR w.title ILIKE $1 OR m.name ILIKE $1 OR c.name ILIKE $1 OR w.assigned_to ILIKE $1) AND ($2='' OR w.status=$2) ORDER BY w.id DESC LIMIT 700`,[term,status])).rows)}catch(e){next(e)}});

app.get('/api/admin/announcements',auth,siteAdmin,async(req,res,next)=>{try{res.json((await q(`SELECT a.*,u.name created_by_name FROM announcements a LEFT JOIN users u ON u.id=a.created_by ORDER BY a.id DESC LIMIT 200`)).rows)}catch(e){next(e)}});
app.post('/api/admin/announcements',auth,siteAdmin,async(req,res,next)=>{try{const title=clean(req.body.title),body=clean(req.body.body),level=['info','warning','critical','success'].includes(req.body.level)?req.body.level:'info';if(title.length<3||body.length<3)return res.status(400).json({error:'Başlık ve duyuru metni gerekli'});const r=(await q(`INSERT INTO announcements(title,body,level,is_active,publish_at,expires_at,created_by) VALUES($1,$2,$3,$4,COALESCE($5::timestamptz,NOW()),$6::timestamptz,$7) RETURNING *`,[title,body,level,req.body.is_active!==false,nil(req.body.publish_at),nil(req.body.expires_at),req.user.id])).rows[0];await adminAudit(req,'announcement_created','announcement',r.id,{title});res.status(201).json(r)}catch(e){next(e)}});
app.patch('/api/admin/announcements/:id',auth,siteAdmin,async(req,res,next)=>{try{const title=clean(req.body.title),body=clean(req.body.body),level=['info','warning','critical','success'].includes(req.body.level)?req.body.level:'info';const r=(await q(`UPDATE announcements SET title=$1,body=$2,level=$3,is_active=$4,publish_at=COALESCE($5::timestamptz,publish_at),expires_at=$6::timestamptz,updated_at=NOW() WHERE id=$7 RETURNING *`,[title,body,level,req.body.is_active!==false,nil(req.body.publish_at),nil(req.body.expires_at),req.params.id])).rows[0];if(!r)return res.status(404).json({error:'Duyuru bulunamadı'});await adminAudit(req,'announcement_updated','announcement',r.id,{title});res.json(r)}catch(e){next(e)}});
app.delete('/api/admin/announcements/:id',auth,siteAdmin,async(req,res,next)=>{try{await q('DELETE FROM announcements WHERE id=$1',[req.params.id]);await adminAudit(req,'announcement_deleted','announcement',req.params.id);res.json({ok:true})}catch(e){next(e)}});

app.get('/api/admin/articles',auth,siteAdmin,async(req,res,next)=>{try{res.json((await q(`SELECT a.*,u.name updated_by_name FROM knowledge_articles a LEFT JOIN users u ON u.id=a.updated_by ORDER BY a.updated_at DESC LIMIT 300`)).rows)}catch(e){next(e)}});
app.post('/api/admin/articles',auth,siteAdmin,async(req,res,next)=>{try{const title=clean(req.body.title),category=clean(req.body.category)||'Genel',summary=clean(req.body.summary),body=clean(req.body.body),source=clean(req.body.source),standard=clean(req.body.standard).slice(0,160),revisionDate=nil(req.body.revision_date),relatedTools=Array.isArray(req.body.related_tools)?req.body.related_tools.slice(0,30):[],relatedSystems=Array.isArray(req.body.related_systems)?req.body.related_systems.slice(0,30):[];if(title.length<3||body.length<5)return res.status(400).json({error:'Başlık ve içerik gerekli'});const base=slug(req.body.slug||title);let articleSlug=base;for(let i=1;(await q('SELECT 1 FROM knowledge_articles WHERE slug=$1',[articleSlug])).rows.length;i++)articleSlug=`${base}-${i+1}`;const r=(await q(`INSERT INTO knowledge_articles(slug,title,category,summary,body,source,standard,revision_date,related_tools,related_systems,is_published,created_by,updated_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,$10::jsonb,$11,$12,$12) RETURNING *`,[articleSlug,title,category,summary,body,source,standard,revisionDate,JSON.stringify(relatedTools),JSON.stringify(relatedSystems),req.body.is_published!==false,req.user.id])).rows[0];await adminAudit(req,'article_created','article',r.id,{title,slug:articleSlug});res.status(201).json(r)}catch(e){next(e)}});
app.patch('/api/admin/articles/:id',auth,siteAdmin,async(req,res,next)=>{try{const title=clean(req.body.title),category=clean(req.body.category)||'Genel',summary=clean(req.body.summary),body=clean(req.body.body),source=clean(req.body.source),standard=clean(req.body.standard).slice(0,160),revisionDate=nil(req.body.revision_date),relatedTools=Array.isArray(req.body.related_tools)?req.body.related_tools.slice(0,30):[],relatedSystems=Array.isArray(req.body.related_systems)?req.body.related_systems.slice(0,30):[];const r=(await q(`UPDATE knowledge_articles SET title=$1,category=$2,summary=$3,body=$4,source=$5,standard=$6,revision_date=$7,related_tools=$8::jsonb,related_systems=$9::jsonb,is_published=$10,updated_by=$11,updated_at=NOW() WHERE id=$12 RETURNING *`,[title,category,summary,body,source,standard,revisionDate,JSON.stringify(relatedTools),JSON.stringify(relatedSystems),req.body.is_published!==false,req.user.id,req.params.id])).rows[0];if(!r)return res.status(404).json({error:'İçerik bulunamadı'});await adminAudit(req,'article_updated','article',r.id,{title});res.json(r)}catch(e){next(e)}});
app.delete('/api/admin/articles/:id',auth,siteAdmin,async(req,res,next)=>{try{await q('DELETE FROM knowledge_articles WHERE id=$1',[req.params.id]);await adminAudit(req,'article_deleted','article',req.params.id);res.json({ok:true})}catch(e){next(e)}});

app.get('/api/admin/logs',auth,siteAdmin,async(req,res,next)=>{try{const limit=Math.min(500,Math.max(20,num(req.query.limit,150)));res.json((await q(`SELECT l.*,u.name admin_name,u.email admin_email FROM admin_action_log l LEFT JOIN users u ON u.id=l.admin_user_id ORDER BY l.id DESC LIMIT $1`,[limit])).rows)}catch(e){next(e)}});
app.get('/api/admin/security',auth,siteAdmin,async(req,res,next)=>{try{const [stats,events]=await Promise.all([q(`SELECT (COUNT(*) FILTER(WHERE success AND created_at>=NOW()-INTERVAL '24 hours'))::int successful_24h,(COUNT(*) FILTER(WHERE NOT success AND created_at>=NOW()-INTERVAL '24 hours'))::int failed_24h,(COUNT(DISTINCT ip) FILTER(WHERE NOT success AND created_at>=NOW()-INTERVAL '24 hours'))::int failed_ips_24h,(SELECT COUNT(*) FROM users WHERE NOT is_active)::int blocked_accounts FROM login_events`),q(`SELECT l.id,l.email,l.success,l.reason,l.ip,l.user_agent,l.created_at,u.name user_name FROM login_events l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.id DESC LIMIT 250`)]);res.json({stats:stats.rows[0],events:events.rows})}catch(e){next(e)}});
app.get('/api/admin/settings',auth,siteAdmin,async(req,res,next)=>{try{res.json(await getSystemSettings(true))}catch(e){next(e)}});
app.patch('/api/admin/settings',auth,siteAdmin,async(req,res,next)=>{try{const allowed=['site_name','registrations_enabled','maintenance_mode','support_email','allow_file_uploads'];for(const k of allowed)if(Object.prototype.hasOwnProperty.call(req.body,k))await q(`INSERT INTO system_settings(key,value,updated_by,updated_at) VALUES($1,$2::jsonb,$3,NOW()) ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_by=EXCLUDED.updated_by,updated_at=NOW()`,[k,JSON.stringify(req.body[k]),req.user.id]);settingsCache.at=0;await adminAudit(req,'settings_updated','settings',null,Object.fromEntries(allowed.filter(k=>k in req.body).map(k=>[k,req.body[k]])));res.json(await getSystemSettings(true))}catch(e){next(e)}});
app.get('/api/admin/support',auth,siteAdmin,async(req,res,next)=>{try{res.json((await q(`SELECT t.*,u.name user_name,u.email user_email,c.name company_name FROM support_tickets t LEFT JOIN users u ON u.id=t.user_id LEFT JOIN companies c ON c.id=t.company_id ORDER BY CASE t.status WHEN 'open' THEN 0 WHEN 'in_progress' THEN 1 ELSE 2 END,t.id DESC LIMIT 400`)).rows)}catch(e){next(e)}});
app.patch('/api/admin/support/:id',auth,siteAdmin,async(req,res,next)=>{try{const status=['open','in_progress','closed'].includes(req.body.status)?req.body.status:'open',note=clean(req.body.admin_note);const r=(await q('UPDATE support_tickets SET status=$1,admin_note=$2,updated_at=NOW() WHERE id=$3 RETURNING *',[status,note,req.params.id])).rows[0];if(!r)return res.status(404).json({error:'Destek kaydı bulunamadı'});await adminAudit(req,'support_updated','support',r.id,{status});res.json(r)}catch(e){next(e)}});

app.get('/robots.txt',(req,res)=>res.type('text/plain').send('User-agent: *\nAllow: /\nDisallow: /app\nDisallow: /admin\nSitemap: https://dijitalmakinaci.pro/sitemap.xml\n'));
app.get('/sitemap.xml',async(req,res,next)=>{try{const base=(clean(process.env.PUBLIC_BASE_URL)||'https://dijitalmakinaci.pro').replace(/\/$/,'');const staticPaths=['/','/hesaplamalar/iso-286-tolerans','/hesaplamalar/kilavuz-on-delik','/hesaplamalar/cnc-kesme','/hesaplamalar/rulman-kod','/hesaplamalar/hidrolik'];const articles=(await q('SELECT slug,updated_at FROM knowledge_articles WHERE is_published=true ORDER BY updated_at DESC')).rows;const urls=[...staticPaths.map(urlPath=>({loc:base+urlPath,lastmod:null})),...articles.map(x=>({loc:`${base}/teknik/${encodeURIComponent(x.slug)}`,lastmod:new Date(x.updated_at).toISOString()}))];res.type('application/xml').send(`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map(x=>`<url><loc>${x.loc.replace(/&/g,'&amp;')}</loc>${x.lastmod?`<lastmod>${x.lastmod}</lastmod>`:''}</url>`).join('')}</urlset>`)}catch(e){next(e)}});
app.get('/api/health',async(req,res)=>{let database='ok',migration=null;try{await q('SELECT 1');migration=(await q('SELECT name FROM schema_migrations ORDER BY name DESC LIMIT 1')).rows[0]?.name||null}catch{database='error'}const storageHealth=await storage.health(),mail=mailConfigured()?'configured':'unconfigured',storageStatus=storageHealth.status;res.status(database==='ok'?200:503).json({ok:database==='ok',version:APP_VERSION,commit:String(process.env.RENDER_GIT_COMMIT||'').slice(0,40)||null,checks:{database,mail,storage:storageStatus,migration},product:`Dijital Makinacı V${APP_VERSION} Pro CMMS`})});
app.use('/api',(req,res)=>res.status(404).json({error:'API endpoint bulunamadı'}));
app.get('*',(req,res)=>{res.status(404);return rootUiFile(res,'not-found.html','html')});
app.use((err,req,res,next)=>{console.error(err);if(err?.code==='LIMIT_FILE_SIZE')return res.status(413).json({error:'Dosya en fazla 5 MB olabilir'});const status=Number(err?.status);if(status>=400&&status<500)return res.status(status).json({error:clean(err.message)||'İşlem reddedildi'});res.status(500).json({error:'Sunucu hatası'})});

initDb().then(()=>{const server=app.listen(PORT,HOST,()=>console.log(`Dijital Makinacı V${APP_VERSION} http://${HOST}:${PORT}`));server.keepAliveTimeout=120000;server.headersTimeout=120000;const firstSweep=setTimeout(runOperationalJobs,5000);firstSweep.unref?.();const interval=setInterval(runOperationalJobs,15*60*1000);interval.unref?.()}).catch(e=>{console.error('DB init hatası:',e);process.exit(1)});
